Section CANSEC1. Context {rc : runConstT}.

Section SKGA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x10 x25 x26 x27 : word).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl st skip n : Z) (sorted : list (option Z)) (js jt : list byte)
            (ncells : nat) (c : deltX2) (R : Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HST : 0 <= st.
  Hypothesis HSK : 0 < skip < 2^31.
  Hypothesis HN : n = (skip + 7) / 8.
  Hypothesis HEND : st + 8 * n <= Z.of_nat ncells.
  Hypothesis HDT4 : ablk (DT + 4) (DT + 4 + 4 * Z.of_nat ncells).
  Hypothesis HWK : ablk WK (WK + 8704).
  Hypothesis NCB : Z.of_nat ncells <= 4096.
  Hypothesis LJS : zlen js = 256.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= WK \/ WK + 8704 <= DT + 4.
  Hypothesis DSP : DT + 4 + 4 * Z.of_nat ncells <= SPA.
  Hypothesis WSP : WK + 8704 <= SPA.
  Hypothesis KSP : KHIGH <= SPA.
  Hypothesis SP47 : SPA + 832 <= 2^47.
  Hypothesis UDT : unpoisoned m0 (DT + 4) (DT + 4 + 4 * Z.of_nat ncells).
  Hypothesis RDT : rng RNG (DT + 4) (4 * Z.of_nat ncells).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 4 * Z.of_nat ncells + DT mod 8)).
  Hypothesis AW : appW (X2WA SPA DT ncells).
  Hypothesis HR : 0 <= R < 2^64.
  Hypothesis LO0 : le2 (Z_to_bv 64 R) = [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256)].
  Hypothesis HI0 : le2 (Z_to_bv 64 (R ≫ 16)) = [Z_to_bv 8 (x2_nbBits c); Z_to_bv 8 (x2_len c)].
  Hypothesis LO1 : le2 (Z_to_bv 64 (R ≫ 32)) = [Z_to_bv 8 (x2_seq c); Z_to_bv 8 (x2_seq c / 256)].
  Hypothesis HI1 : le2 (Z_to_bv 64 (R ≫ 48)) = [Z_to_bv 8 (x2_nbBits c); Z_to_bv 8 (x2_len c)].
  Notation INV m1 dt := (x2fA_inv m0 m1 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt).
  (* [comment removed for export] *)
  Notation LS k m x13 x21 x22 x23 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp (Z_to_bv 64 (R ≫ 32)) (Z_to_bv 64 (R ≫ 16)) (Z_to_bv 64 (DT + 20 + 32 * k))
             (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 (Z_to_bv 64 skip) (Z_to_bv 64 (8 * k)) x13 (Z_to_bv 64 (DT + 12 + 32 * k))
             (Z_to_bv 64 (R ≫ 48)) (Z_to_bv 64 (DT + 20 + 32 * k)) (Z_to_bv 64 (DT + 27 + 32 * k)) (Z_to_bv 64 (4 * st))
             (Z_to_bv 64 R) (Z_to_bv 64 (DT + 4 + 32 * k)) x21 x22 x23 (Z_to_bv 64 2147450880) x25 x26 x27
             (Z_to_bv 64 (DT + 19 + 32 * k)) (Z_to_bv 64 (DT + 35 + 32 * k)) (Z_to_bv 64 (DT + 28 + 32 * k))
             (Z_to_bv 64 (DT + 11 + 32 * k)))
        F (Z_to_bv 64 0x82478) fc None m (seg_rom asegs)).

  Lemma skgA_chunks : forall f k dtk dtR m1 mC (x13 x21 x22 x23 : word),
    Z.of_nat f = n - k -> 0 <= k < n ->
    store_run (Z.to_nat (8 * (n - k))) dtk (st + 8 * k) c = Ok dtR ->
    INV m1 dtk -> munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells)] mC m1 -> wmono asegs mC m1 ->
    (forall m2 (y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y19 y20 y21 y22 y23 y28 y29 y30 y31 : word),
       INV m2 dtR -> munch [(DT + 4, DT + 4 + 4 * Z.of_nat ncells)] mC m2 -> wmono asegs mC m2 ->
       evtF asegs RNG Q
         (MS (mkR x1 (Z_to_bv 64 SPA) gp tp y5 y6 y7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) y10 y11 y12 y13 y14 y15 y16 y17
                  (Z_to_bv 64 (4 * st)) y19 y20 y21 y22 y23 (Z_to_bv 64 2147450880) x25 x26 x27 y28 y29 y30 y31)
             F (Z_to_bv 64 0x825ec) fc None m2 (seg_rom asegs))) ->
